using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using PaymentBatchProcessingService.Domain.Entities;
using PaymentBatchProcessingService.Domain.Helpers;

namespace PaymentBatchProcessingService.Infrastructure.DB.Configurations;

public sealed class BankAccountConfiguration : IEntityTypeConfiguration<BankAccount>
{
    public void Configure(EntityTypeBuilder<BankAccount> builder)
    {
        //SQL table name
        builder.ToTable("BankAccounts");

        //Primary key configuration, GUID is generated by the application, not the database
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).ValueGeneratedNever();

        //LegalEntityId is required foreign key
        builder.Property(x => x.LegalEntityId).IsRequired();

        //BankId is required foreign key
        builder.Property(x => x.BankId).IsRequired();

        //AccountIdentifier is required, has a maximum length, and is stored as non-Unicode in the database
        builder.Property(x => x.AccountIdentifier).IsRequired().HasMaxLength(Constants.MaxAccountIdentifierLength).IsUnicode(false);

        //Currency is required, has a maximum length of 3, and is stored as non-Unicode in the database
        builder.Property(x => x.Currency).HasConversion<string>().HasMaxLength(Constants.MaxCurrencyLength).IsUnicode(false).IsRequired();

        //CreatedAtUtc is required and is stored as UTC in the database
        builder.Property(x => x.CreatedAtUtc).HasColumnType("datetime2")
            .HasConversion(
                value => value,
                value => DateTime.SpecifyKind(value, DateTimeKind.Utc)).IsRequired();

        //Each BankAccount has one LegalEntity and one Bank, with foreign key constraints and restricted delete behavior
        builder.HasOne<LegalEntity>().WithMany().HasForeignKey(x => x.LegalEntityId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne<Bank>().WithMany().HasForeignKey(x => x.BankId).OnDelete(DeleteBehavior.Restrict);
    }
}
